package com.daytracker.categories;

import java.util.UUID;

import jakarta.validation.constraints.NotNull;

public final class CategoryRequests {

	private CategoryRequests() {
	}

	/** The id is generated by the client so a retried create is idempotent. */
	public record Create(@NotNull UUID id, @NotNull String name, @NotNull String color) {
	}

	/** Null properties are left unchanged; no category property can be cleared. */
	public record Update(@NotNull Long version, String name, String color, Boolean archived) {
	}

}
